import type { Hex } from "viem";

// Runtime bytecode of the contracts in TestTokens.sol, compiled with solc 0.8.30 (default
// settings). Regenerate from a foundry project containing TestTokens.sol:
//   forge inspect src/TestTokens.sol:PlainToken deployedBytecode
//   forge inspect src/TestTokens.sol:SharesToken deployedBytecode

/** `balanceOf` is a plain mapping at storage slot 3. */
export const PLAIN_TOKEN_RUNTIME: Hex =
  "";

/** `balanceOf` is `sharesOf * 2`: a derived balance that storage writes cannot set exactly. */
export const SHARES_TOKEN_RUNTIME: Hex =
  "";
